eases the allowance granted to an account by the sender.This is an alternative to {approve} that can be used as a mitigation for transaction ordering problems."}},"version":1}},"settings":{"compilationTarget":{"@animoca/ethereum-contracts/contracts/token/ERC20/interfaces/IERC20Allowance.sol":"IERC20Allowance"},"evmVersion":"london","libraries":{},"metadata":{"bytecodeHash":"ipfs","useLiteralContent":true},"optimizer":{"enabled":true,"runs":99999},"remappings":[]},"sources":{"@animoca/ethereum-contracts/contracts/token/ERC20/interfaces/IERC20Allowance.sol":{"content":"// SPDX-License-Identifier: MIT
